    "etf.rssb.layer.0.body": { "zh": "追蹤全球市值加權股票（SPTM + VXUS 等），目標覆蓋全球可投資股票市場。", "en": "Tracks global cap-weighted equities (SPTM, VXUS, and similar holdings) to cover the investable global stock market." },
    "etf.rssb.layer.0.title": { "zh": "第一層 · 全球股票 100%", "en": "Layer 1 · Global stocks 100%" },
    "etf.rssb.layer.1.body": { "zh": "等權配置 2 年、5 年、10 年、長天期美債期貨，提供與股票低相關的債券曝險。", "en": "Equal-weight 2-, 5-, 10-, and long Treasury futures for bond exposure that is typically lowly correlated with stocks." },
