    "etf.rssx.l2.kicker": { "zh": "第二層策略 · 黃金＋比特幣（風險平價）", "en": "Layer 2 strategy · Gold + Bitcoin (risk parity)" },
    "etf.rssx.layer.0.body": { "zh": "大型股美國股市（SPYM 等）。", "en": "Large-cap US equity market (e.g. SPYM)." },
    "etf.rssx.layer.0.title": { "zh": "第一層 · 美國股票 100%", "en": "Layer 1 · US stocks 100%" },
    "etf.rssx.layer.1.body": { "zh": "透過黃金／比特幣期貨與 ETF（如 IBIT），讓兩者風險貢獻盡量相等；波動大者降權。", "en": "Gold and Bitcoin via futures and ETFs (e.g. IBIT); weights aim for equal risk contribution, scaling down the higher-vol asset." },
    "etf.rssx.layer.1.title": { "zh": "第二層 · 黃金＋比特幣 100%", "en": "Layer 2 · Gold + Bitcoin 100%" },
    "etf.rssx.name": { "zh": "美股＋黃金／比特幣", "en": "U.S. Stocks & Gold/Bitcoin" },
    "etf.rssx.nav.desc": { "zh": "目前頁面為 RSSX。其他標的：", "en": "Current page: RSSX. Other tickers:" },
