    "etf.rssx.perf.\u6210\u7acb\u4ee5\u4f86": { "zh": "成立以來", "en": "Since inception" },
    "etf.rssx.stack": { "zh": "黃金＋比特幣（風險平價）", "en": "Gold + Bitcoin (risk parity)" },
    "etf.rssx.tagline": { "zh": "100% 美股 ＋ 100% 黃金／比特幣——依 63 日波動做風險平價，每月再平衡。", "en": "100% US stocks plus 100% gold and Bitcoin—risk parity on 63-day volatility, rebalanced monthly." },
    "etf.rssx.tim_note": { "zh": "Tim Wei 實驗目前尚未配置 RSSX，但已準備相關說明貼文。", "en": "Tim Wei does not hold RSSX yet; explanatory posts are prepared." },
    "etf.rssx.why.0.desc": { "zh": "底倉配置 100% 美國大盤股。第二層則配置 100% 黃金＋比特幣。黃金與比特幣（被譽為數位黃金）作為另類貨幣與硬資產，在抗通膨、反法幣貶值以及防範總體信用危機方面，能發揮與傳統股債完全不同的保護與回報作用。", "en": "Layer 1 is <strong>100% US large-cap stocks</strong>. Layer 2 is <strong>100% gold and Bitcoin</strong>. As alternative monetary and hard assets, they can behave differently from traditional stocks and bonds—inflation hedging, fiat debasement, and credit-stress scenarios." },
    "etf.rssx.why.0.title": { "zh": "傳統美股與另類硬資產（Hard Assets）的結合", "en": "US stocks plus hard assets" },
    "etf.rssx.why.1.desc": { "zh": "第二層並非簡單 of 50/50 分配，而是透過風險平價模型，根據兩者的歷史波動率動態調整配置權重，確保兩者對投資組合的風險貢獻基本相等。這可以有效降低因單一高波動資產（如比特幣）暴跌而對整體組合造成的巨大衝擊。", "en": "Layer 2 is not a static 50/50 split. A risk-parity model adjusts weights from historical volatility so each asset contributes roughly equal risk—helping limit damage when a high-vol leg (e.g. Bitcoin) sells off sharply." },
    "etf.rssx.why.1.title": { "zh": "風險平價（Risk Parity）動態權重調配", "en": "Risk-parity dynamic weights" },
    "etf.rssx.why.2.desc": { "zh": "歷史上，黃金與美股的相關性僅約 0.09，而比特幣與美股的相關性約為 0.23。這種極低的相關性使得第二層另類硬資產在美股回檔時，能產生優秀的分散風險效果，平滑資產淨值波動。", "en": "Historically, gold’s correlation to US stocks is about 0.09; Bitcoin to US stocks about 0.23. That low overlap lets the hard-asset sleeve <strong>diversify US equity drawdowns</strong> and smooth combined NAV volatility." },
    "etf.rssx.why.2.title": { "zh": "極低相關性的多重多元化", "en": "Low-correlation diversification" },
    "etf.rssx.why.3.desc": { "zh": "適合想要在投資組合中加入黃金與比特幣等新世代資產，卻又不想自行開戶、調倉或承受實物存儲安全風險的投資人。投資人只需賣掉 20% 美股改買 RSSX，即可無痛擁有這兩種強大的另類資產。", "en": "For investors who want gold and Bitcoin without separate accounts, rebalancing, or physical custody—sell 20% US equity, buy 20% RSSX, and <strong>stack both alternatives</strong> without giving up the stock sleeve." },
    "etf.rssx.why.3.title": { "zh": "一檔滿足所有防護與增值需求", "en": "One-ticket access" },
