    "etf.rssy.layer.1.body": { "zh": "系統化在多商品、匯率、債券、股指期貨上做多／做空，收割 roll yield。", "en": "Systematic long/short across commodity, FX, bond, and equity index futures to harvest roll yield." },
    "etf.rssy.layer.1.title": { "zh": "第二層 · 期貨 Carry 100%", "en": "Layer 2 · Futures carry 100%" },
