    "guide.holdings.analogy.margin.label": { "zh": "會計記帳 (官方持倉表)", "en": "Accounting (official holdings)" },
    "guide.holdings.analogy.notional.desc": { "zh": "每投入 $1，即疊加 $1 基礎 ＋ $1 策略，獲取 200% 的<strong>名義曝險</strong>。", "en": "Each $1 invested stacks $1 base + $1 overlay for <strong>200% notional exposure</strong>." },
