    "guide.learn.compare.r3.lev": { "zh": "—", "en": "—" },
    "guide.learn.compare.r3.rs": { "zh": "美國公債、管理期貨（趨勢追蹤）、期貨展期收益、併購套利…", "en": "US Treasuries, managed futures (trend), futures yield, merger arb…" },
    "guide.learn.compare.title": { "zh": "200% 曝險，但不是同一種風險", "en": "200% exposure, not the same risk" },
    "guide.learn.core.analogy.1": { "zh": "100 元買股票 → 100 元股票曝險（100%）", "en": "Buy stocks with $100 → $100 stock exposure (100%)" },
    "guide.learn.core.analogy.2": { "zh": "100 元買正二 → 200 元同一種股票曝險（200%）", "en": "Buy 2x leveraged ETF with $100 → $200 of the same stock exposure (200%)" },
    "guide.learn.core.analogy.3": { "zh": "100 元買報酬疊加 ETF → 100 元股票 ＋ 100 元不同路的資產（例如美國公債、管理期貨（趨勢追蹤）、期貨展期收益）", "en": "Buy a Return Stacked ETF with $100 → $100 stocks + $100 of a different asset class (e.g. US Treasuries, managed futures, futures yield)" },
    "guide.learn.core.kicker": { "zh": "核心概念", "en": "Core idea" },
    "guide.learn.core.note": { "zh": "同樣是 200% 總曝險，但第二層與第一層低相關，波動通常小於槓桿單一資產。這就是「讓每一塊錢工作兩次，但兩次做不同的事」。", "en": "Same 200% total exposure, but Layer 2 is low-correlated with Layer 1, so volatility is usually lower than levering a single asset. That is: make each dollar work twice, on two different jobs." },
    "guide.learn.core.title": { "zh": "Return Stacking 是什麼？", "en": "What is Return Stacking?" },
    "guide.learn.hero.lead": { "zh": "這個網站是完整教材：先把 Return Stacking 與 ETF 家族講清楚，再到總覽頁看 Tim Wei 的實測數據。Threads、FB 等社群貼文只挑幾個重點，完整內容都在這裡。", "en": "This site is the full curriculum: understand Return Stacking and the ETF lineup first, then review Tim Wei's live results. Social posts only highlight a few points—the full material is here." },
    "guide.learn.hero.tag": { "zh": "學習中心", "en": "Learning hub" },
