    "layer2.viz.us-bonds.cap": { "zh": "Treasury ladder · equal weight", "en": "Treasury ladder · equal weight" },
    "layer2.viz.us-bonds.long": { "zh": "長天期", "en": "Long" },
    "meta.desc.etf-rsba": { "zh": "100% 美國公債 ＋ 100% 併購套利——在債券底層上疊事件驅動型策略。", "en": "100% US Treasuries + 100% merger arbitrage—event-driven overlay on a bond base." },
    "meta.desc.etf-rsbt": { "zh": "100% 美國債券 ＋ 100% 管理期貨趨勢——在債券底層上疊 CTA。", "en": "100% US bonds + 100% managed-futures trend—a CTA overlay on a bond base." },
    "meta.desc.etf-rsby": { "zh": "100% 美國債券 ＋ 100% 跨資產期貨 Carry——RSBY 是 RSSY 的債券底層版。", "en": "100% US bonds + 100% cross-asset futures carry—the bond-base version of RSSY." },
    "meta.desc.etf-rsit": { "zh": "100% 已開發市場國際股 ＋ 100% 管理期貨趨勢——RSST 的國際版。", "en": "100% developed-market international stocks + 100% managed-futures trend—the international RSST." },
    "meta.desc.etf-rssb": { "zh": "Return Stacked 系列的地基：100% 全球股 ＋ 100% 美債，一檔 ETF 搞定 200% 曝險。", "en": "The foundation of Return Stacked: 100% global stocks + 100% US Treasuries in one ETF." },
    "meta.desc.etf-rsst": { "zh": "底下全倉大盤美股，上面再疊一層會做多也會做空的管理期貨趨勢策略。", "en": "Full US large-cap exposure plus a long/short managed-futures trend overlay." },
    "meta.desc.etf-rssx": { "zh": "100% 美股 ＋ 100% 黃金／比特幣——依 63 日波動做風險平價，每月再平衡。", "en": "100% US stocks + 100% gold/Bitcoin with 63-day vol risk parity, rebalanced monthly." },
    "meta.desc.etf-rssy": { "zh": "100% 美股 ＋ 100% 跨資產期貨 Carry（展期收益）策略。", "en": "100% US stocks + 100% cross-asset futures carry (roll-yield) strategy." },
    "meta.desc.etfs": { "zh": "8 檔 Return Stacked ETF 完整說明：結構、費率、持股、績效、相關性。", "en": "Full guide to all 8 Return Stacked ETFs: structure, fees, holdings, performance, correlations." },
    "meta.desc.layer2": { "zh": "管理期貨、期貨展期收益、黃金比特幣、併購套利——白話拆解多出來的 100% 在買什麼。", "en": "Managed futures, futures yield, gold/Bitcoin, merger arb—what the extra 100% overlay is doing." },
    "meta.desc.learn": { "zh": "Return Stacking 是什麼？Tim Wei 透明實驗紀錄。先懂概念，再看實測數據。", "en": "What is Return Stacking? Tim Wei's transparent experiment log." },
